actions.script:
def p = ec.web.parameters
try {
    if (!p.productId) { ec.web.sendJsonResponse([success:false, error:'Missing product']); return }
    def code = (p.code ?: '').toString().trim()
    def ev = ec.entity.find("mantle.product.Product").condition("productId", p.productId).one()
    if (!ev) { ec.web.sendJsonResponse([success:false, error:'Unknown product']); return }
    // Org isolation (ZE-SEC-JSON): only mutate THIS org's products — the MANTLE_ACTIVE_ORG filter
    // does NOT apply in a transition, so verify ownership explicitly (super-admin exempt).
    // Prevents overwriting another tenant's scan code via a forged productId.
    def _bcAo = ec.service.sync().name('zenith.barcode.BarcodeServices.get#AuthorizedActiveOrganization').call().activeOrgId
    def permission=ec.service.sync().name('zenith.base.SecurityServices.check#ModuleWriteAccess').parameters([moduleId:'pos']).call()
    if(!permission.canWrite){ec.web.sendJsonResponse([success:false,error:'Product code write access is required.']);return}
    if (!ec.user.isInGroup('ADMIN') && (!_bcAo || _bcAo == '_NA_' || ev.ownerPartyId != _bcAo)) {
        ec.web.sendJsonResponse([success:false, error:'You do not have access to this product.']); return }
    if(!ev.ownerPartyId){ec.web.sendJsonResponse([success:false,error:'Select an organization-owned product.']);return}
    ec.entity.find('mantle.party.Party').condition('partyId',ev.ownerPartyId).forUpdate(true).disableAuthz().one()
    if (code != '') {
        // Keep the rich ProductBarcode table in sync (mirror this code as the product's
        // primary barcode). A mirror failure rolls back the same transaction.
        ec.service.sync().name("zenith.barcode.BarcodeServices.sync#BarcodeFromPseudoId").parameters([productId:p.productId, code:code]).call()
        if(ec.message.hasError()){ec.web.sendJsonResponse([success:false,error:ec.message.errorsString]);return}
        ec.entity.makeValue("mantle.product.Product").set("productId", p.productId).set("pseudoId", code).update()
        ec.web.sendJsonResponse([success:true, code:code]); return
    }
    // Clearing removes only the primary and preserves/promotes active secondary barcodes.
    def cleared=ec.service.sync().name('zenith.barcode.BarcodeServices.clear#ProductCode').parameters([productId:p.productId]).call()
    if(ec.message.hasError()){ec.web.sendJsonResponse([success:false,error:'Code synchronization failed.']);return}
    ec.web.sendJsonResponse([success:true,code:cleared.code ?: ''])
} catch (Exception e) { ec.message.addError('Could not save the product code.'); ec.web.sendJsonResponse([success:false, error:'Could not save the product code.']) }

def posOrg = ec.service.sync().name('zenith.barcode.BarcodeServices.get#AuthorizedActiveOrganization').call().activeOrgId ?: '__NO_ORGANIZATION__'
barcodeSessionToken=ec.web.sessionToken
def pageSize = 60
def pIdx = 0
try { if (pageIndex) pIdx = (pageIndex as Integer) } catch (Exception ig) { pIdx = 0 }
if (pIdx < 0) pIdx = 0

def catFinder = ec.entity.find("mantle.product.category.ProductCategory")
if (posOrg) catFinder.condition("ownerPartyId", posOrg)
categories = catFinder.orderBy("categoryName").list()

def catProdIds = null
if (catId) {
    catProdIds = [] as Set
    ec.entity.find("mantle.product.category.ProductCategoryMember").condition("productCategoryId", catId).list().each { catProdIds.add(it.productId) }
}

def pf = ec.entity.find("mantle.product.Product").condition("productTypeEnumId", "PtAsset")
    .conditionDate('salesIntroductionDate','salesDiscontinuationDate',ec.user.nowTimestamp)
if (posOrg) pf.condition("ownerPartyId", posOrg)
def candidates = pf.orderBy("productName").limit(5000).list()

// A pseudoId equal to the productId is Moqui's "no code" state (a cleared code reverts to the PK),
// so treat it as empty everywhere — status, dup detection, search, and the row's code box.
def effCode = { pr -> def c = (pr.pseudoId ?: '').trim(); (c == '' || c == pr.productId) ? '' : c }

// Duplicate-code detection across the tenant's current products.
def codeCounts = [:]
candidates.each { pr -> def c = effCode(pr); if (c != '') codeCounts[c] = (codeCounts[c] ?: 0) + 1 }
def dupCodes = codeCounts.findAll { it.value > 1 }.keySet()
missingTotal = candidates.count { effCode(it) == '' }
dupTotal = candidates.count { def c = effCode(it); c != '' && dupCodes.contains(c) }

def termLower = (searchTerm ?: '').toLowerCase().trim()
def filtered = candidates.findAll { pr ->
    (termLower == '' || (pr.productName ?: '').toLowerCase().contains(termLower) || effCode(pr).toLowerCase().contains(termLower)) &&
    (catProdIds == null || catProdIds.contains(pr.productId))
}
totalCount = filtered.size()
pageCount = (int) Math.ceil(totalCount / (double) pageSize)
if (pageCount < 1) pageCount = 1
if (pIdx >= pageCount) pIdx = pageCount - 1
curPage = pIdx
def from = pIdx * pageSize
def to = Math.min(from + pageSize, totalCount)
def pageProds = (from < totalCount) ? filtered.subList(from, to) : []

rows = pageProds.collect { pr ->
    def c = effCode(pr)
    def status = (c == '') ? 'missing' : (dupCodes.contains(c) ? 'dup' : 'ok')
    [productId: pr.productId, productName: (pr.productName ?: pr.productId), code: c, status: status]
}
